from .repository import find_existing_emails, put_contact

_ROW_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row):
    if not isinstance(row, dict):
        raise ValueError("contact row must be an object")
    keys = set(row.keys())
    if keys != _ROW_FIELDS:
        missing = sorted(_ROW_FIELDS - keys, key=str)
        unknown = sorted(keys - _ROW_FIELDS, key=str)
        raise ValueError(f"contact row must have exactly 'email' and 'name' (missing={missing}, unknown={unknown})")
    email = row["email"]
    name = row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("contact email and name must be strings")
    email = email.strip()
    name = name.strip()
    if not name:
        raise ValueError("contact name must be nonempty")
    if any(ch.isspace() for ch in email):
        raise ValueError("contact email must not contain whitespace")
    if email.count("@") != 1:
        raise ValueError("contact email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("contact email must have nonempty local and domain parts")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, list):
        raise ValueError("contacts must be a list")

    normalized = []
    seen = set()
    for row in rows:
        email, name = _normalize_row(row)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        normalized.append((email, name))

    if not normalized:
        return {"inserted": 0, "updated": 0}

    with connection:
        existing = find_existing_emails(connection, (email for email, _ in normalized))
        inserted = 0
        updated = 0
        for email, name in normalized:
            put_contact(connection, email, name)
            if email in existing:
                updated += 1
            else:
                inserted += 1
    return {"inserted": inserted, "updated": updated}
